"use client"

import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from "react"

// Keel Founders Template — a one-page site for Kedhareswer's design + front-end practice for startups.
// The 14 photographs are generated originals served from the component site (see README).
// Motion (measured on the reference at 1440 × 900, see README):
//   load: nav drops in on a critically damped spring, the CTA pill pops, the headline blurs in letter
//   by letter, the subtitle word by word; the hero picture drifts with scroll; headings ink in word by
//   word as they cross the middle of the viewport; blocks rise 20px in 0.6s ease-out-quad.

// #region motion
export const EASE_OUT = "cubic-bezier(.25,.46,.45,.94)" // in-view reveals: 0.6s, y20 (measured: 47% at 28%, 74% at 49%)
export const EASE_TEXT = "cubic-bezier(.12,.23,.5,1)" // hero letters / words / CTA pill
export const NAV_W = 8 // critically damped spring, ω = 8/s (fits the nav drop within 0.01)
export const NAV_DUR = 1.2
export const springAt = (t: number) => (t <= 0 ? 0 : 1 - (1 + NAV_W * t) * Math.exp(-NAV_W * t))
/** The nav spring as a CSS linear() easing over NAV_DUR seconds. */
export function springEasing(steps = 24) {
  const pts: string[] = []
  for (let i = 0; i <= steps; i++) {
    const t = (i / steps) * NAV_DUR
    pts.push(i === steps ? "1" : (Math.round(springAt(t) * 1000) / 1000).toString())
  }
  return "linear(" + pts.join(",") + ")"
}
export const HEAD_DELAY = 1.6 // s — headline letters start
export const HEAD_STAGGER = 16 // ms per letter
export const SUB_DELAY = 2.14 // s — subtitle words start
export const SUB_STAGGER = 25 // ms per word
export const NAVL_DELAY = 1.68 // s — nav link letters
export const NAVL_STAGGER = 30 // ms per letter
export const clamp = (v: number, a: number, b: number) => Math.min(b, Math.max(a, v))
/** Hero picture drift: starts 77px into the scroll, 0.27 px per px, stops at 270px. */
export const heroShift = (scrolled: number) => clamp((scrolled - 77) * 0.27, 0, 270)
/** The nav turns light once 62% of the hero has scrolled away. */
export const navLight = (scrolled: number, heroH: number) => scrolled > heroH * 0.62
/**
 * Ink text: a block's words light up one after another while its top travels from 73.3% of the
 * viewport height up to 33.3% (and go out again on the way back).
 */
export const INK_FROM = 0.733
export const INK_SPAN = 0.4
export const inkProgress = (top: number, vh: number) => (vh > 0 ? clamp((vh * INK_FROM - top) / (vh * INK_SPAN), 0, 1) : 1)
/** How many of a block's n words are lit at progress p: word i lights once p passes i / n. */
export const inkCount = (p: number, n: number) => (p <= 0 ? 0 : Math.min(n, Math.ceil(p * n - 1e-9)))
export const SLIDE_MS = 6000 // testimonial autoplay
export const SLIDE_DUR = 1 // s
export const SLIDE_EASE = "cubic-bezier(.2,.9,.3,1)" // 80% of the way in 0.4s, then a long settle
/** Next slide index for a loop rendered with one cloned first slide at the end. */
export const nextSlide = (i: number, n: number) => (i >= n ? 1 : i + 1)
export const prevSlide = (i: number, n: number) => (i <= 0 ? n - 1 : i - 1)
// #endregion

