  ".kf-track,.kf-pill-label,.kf-pill-dot,.kf-step,.kf-stepgo,.kf-wcard,.kf-link::after{transition:none!important}" +
  ".kf-hero-media{transform:scale(1.05)!important}" +
  "}"

