// ---------------------------------------------------------------- text splitting
/** Letters (each a span with --i) grouped in words so lines only break between words. */
function Letters({ text, start = 0 }: { text: string; start?: number }) {
  let i = start
  const words = text.split(" ")
  return (
    <>
      <span className="kf-sr">{text}</span>
      <span aria-hidden="true">
        {words.map((w, wi) => (
          <span key={wi} className="kf-word" style={{ whiteSpace: "nowrap" }}>
            {w.split("").map((c, ci) => (
              <span key={ci} className="kf-ch" style={{ ["--i" as string]: i++ } as CSSProperties}>
                {c}
              </span>
            ))}
            {wi < words.length - 1 ? <span className="kf-ch" style={{ ["--i" as string]: i++ } as CSSProperties}> </span> : null}
          </span>
        ))}
      </span>
    </>
  )
}
function Words({ text }: { text: string }) {
  const words = text.split(" ")
  return (
    <>
      <span className="kf-sr">{text}</span>
      <span aria-hidden="true">
        {words.map((w, i) => (
          <span key={i}>
            <span className="kf-word" style={{ ["--i" as string]: i } as CSSProperties}>
              {w}
            </span>
            {i < words.length - 1 ? " " : null}
          </span>
        ))}
      </span>
    </>
  )
}
/** Words that ink from 50% to full opacity as they cross the middle of the viewport. */
function Ink({ text, soft }: { text: string; soft?: string }) {
  const words = text.split(" ")
  return (
    <>
      {words.map((w, i) => (
        <span key={i}>
          <span className="kf-ink" data-ink="">
            {w}
          </span>{" "}
        </span>
      ))}
      {soft ? (
        <span className="kf-ink kf-soft" data-ink="">
          {soft}
        </span>
      ) : null}
    </>
  )
}
const rv = (y?: number, d?: number, s?: number) =>
  ({ ...(y !== undefined ? { ["--y"]: y + "px" } : null), ...(d ? { ["--d"]: d + "s" } : null), ...(s ? { ["--s"]: s } : null) }) as CSSProperties

// ---------------------------------------------------------------- component
export interface KeelFoundersTemplateProps {
  /** Hero and testimonial height. A definite length; never a percentage. */
  height?: string
  /** Where "Book a call", "Contact" and the pricing CTA write to. */
  email?: string
  /** Base URL of the rendered pictures (hero, services, testimonials, process, work, cta). */
  assetBase?: string
  className?: string
  style?: CSSProperties
}

export default function KeelFoundersTemplate({
  height = "100svh",
  email = "kedhareswer.12110626@gmail.com",
  assetBase,
  className,
  style,
}: KeelFoundersTemplateProps) {
  const rootRef = useRef(null as HTMLDivElement | null)
  const navRef = useRef(null as HTMLElement | null)
  const heroRef = useRef(null as HTMLElement | null)
  const mediaRef = useRef(null as HTMLDivElement | null)
  const [slide, setSlide] = useState(0)
  const [snap, setSnap] = useState(false)
  const [menu, setMenu] = useState(false)
  const [sent, setSent] = useState(false)
  const [ready, setReady] = useState(false)
  const st = useRef({ reduced: false, quotesVisible: false, paused: false })
  const pic = (k: string) => (assetBase ? assetBase.replace(/\/?$/, "/") + k + ".webp" : img(k))
  const mail = "mailto:" + email

  // scroll: hero drift, nav tone, ink words; in-view reveals; reduced motion
  useEffect(() => {
    const root = rootRef.current
    if (!root) return
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)")
    st.current.reduced = mq.matches
    const onMq = () => {
      st.current.reduced = mq.matches
      schedule()
    }
    mq.addEventListener("change", onMq)

    const io = new IntersectionObserver(
      (list) => {
        for (const e of list) {
          if (e.isIntersecting) {
            e.target.classList.add("kf-in")
            io.unobserve(e.target)
          }
        }
      },
      { rootMargin: "0px" },
    )
    root.querySelectorAll("[data-rv]").forEach((el) => io.observe(el))

    const qs = root.querySelector("[data-quotes]")
    const qio = new IntersectionObserver((list) => {
      st.current.quotesVisible = list.some((x) => x.isIntersecting)
    })
    if (qs) qio.observe(qs)

    const blocks = (Array.from(root.querySelectorAll("[data-inkblock]")) as HTMLElement[]).map((el) => ({
      el,
      words: Array.from(el.querySelectorAll("[data-ink]")) as HTMLElement[],
      lit: 0,
    }))
    let raf = 0
    let heroLight = false
    const frame = () => {
      raf = 0
      const hero = heroRef.current
      const vh = window.innerHeight
      if (hero) {
        const r = hero.getBoundingClientRect()
        const scrolled = -r.top
        const media = mediaRef.current
        if (media) media.style.transform = st.current.reduced ? "scale(1.05)" : "translateY(" + heroShift(scrolled).toFixed(2) + "px) scale(1.05)"
        const light = navLight(scrolled, r.height)
        if (light !== heroLight) {
          heroLight = light
          navRef.current?.classList.toggle("kf-light", light)
        }
      }
      for (const b of blocks) {
        const n = b.words.length
        const want = st.current.reduced ? n : inkCount(inkProgress(b.el.getBoundingClientRect().top, vh), n)
        if (want === b.lit) continue
        for (let i = Math.min(want, b.lit); i < Math.max(want, b.lit); i++) b.words[i].classList.toggle("kf-lit", i < want)
        b.lit = want
      }
    }
    const schedule = () => {
      if (!raf) raf = window.requestAnimationFrame(frame)
    }
    schedule()
    window.addEventListener("scroll", schedule, { passive: true })
    window.addEventListener("resize", schedule)
    return () => {
      io.disconnect()
      qio.disconnect()
      mq.removeEventListener("change", onMq)
      window.removeEventListener("scroll", schedule)
      window.removeEventListener("resize", schedule)
      if (raf) window.cancelAnimationFrame(raf)
    }
  }, [])

  // testimonial autoplay (paused off screen, on hover/focus, and under reduced motion)
  useEffect(() => {
    const id = window.setInterval(() => {
      const s = st.current
      if (s.reduced || !s.quotesVisible || s.paused || document.hidden) return
      setSnap(false)
      setSlide((i) => nextSlide(i, QUOTES.length))
    }, SLIDE_MS)
    return () => window.clearInterval(id)
  }, [])
  // after the clone of slide 1 lands, jump back to the real slide 1 without a transition
  const onTrackEnd = () => {
    if (slide === QUOTES.length) {
      setSnap(true)
      setSlide(0)
    }
  }
  const go = (dir: number) => {
    setSnap(false)
    setSlide((i) => (dir > 0 ? nextSlide(i, QUOTES.length) : prevSlide(i, QUOTES.length)))
  }

  const jump = (id: string) => {
    setMenu(false)
    const el = rootRef.current?.querySelector("#kf-" + id)
    el?.scrollIntoView({ behavior: st.current.reduced ? "auto" : "smooth", block: "start" })
  }
  const toTop = () => {
    setMenu(false)
    rootRef.current?.scrollIntoView({ behavior: st.current.reduced ? "auto" : "smooth", block: "start" })
  }

  const pill = (label: string): ReactNode => (
    <a className="kf-pill" href={mail}>
      <span className="kf-pill-dot kf-b" aria-hidden="true">
        <Arrow />
      </span>
      <span className="kf-pill-label">
        <span className="kf-sr">{label}</span>
        <span aria-hidden="true">
          {label.split("").map((c, i) => (
            <span key={i} className="kf-ch" style={{ ["--i" as string]: i } as CSSProperties}>
              {c}
            </span>
          ))}
        </span>
      </span>
      <span className="kf-pill-dot kf-a" aria-hidden="true">
        <Arrow />
      </span>
    </a>
  )

  return (
    <div ref={rootRef} className={"kf-root" + (className ? " " + className : "")} style={style}>
      <style>{FONTS + CSS}</style>

      {/* ---- nav */}
      <header ref={navRef} className="kf-navbar">
        <div className="kf-wrap kf-nav">
          <button type="button" className="kf-brand" onClick={toTop} aria-label="Kedhareswer, back to top">
            <Mark />
            <span>Kedhareswer</span>
          </button>
          <nav className="kf-links" aria-label="Sections">
            {NAV.map((n) => (
              <button key={n.id} type="button" className="kf-link" onClick={() => jump(n.id)}>
                <span>
                  <Letters text={n.label} />
                </span>
              </button>
            ))}
            <a className="kf-link" href={mail}>
              <span>
                <Letters text="Contact" />
              </span>
            </a>
          </nav>
          <button type="button" className="kf-menu" aria-expanded={menu} aria-controls="kf-sheet" aria-label={menu ? "Close menu" : "Open menu"} onClick={() => setMenu((m) => !m)}>
            <svg viewBox="0 0 16 16" aria-hidden="true">
              <path d={menu ? "M3 3l10 10M13 3 3 13" : "M2 4h12M2 8h12M2 12h12"} stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" />
            </svg>
          </button>
        </div>
        <div id="kf-sheet" className={"kf-sheet" + (menu ? " kf-open" : "")}>
          <div className="kf-wrap">
            {NAV.map((n) => (
              <button key={n.id} type="button" className="kf-link" tabIndex={menu ? 0 : -1} onClick={() => jump(n.id)}>
                {n.label}
              </button>
            ))}
            <a className="kf-link" href={mail} tabIndex={menu ? 0 : -1}>
              Contact
            </a>
          </div>
        </div>
      </header>

      {/* ---- hero */}
      <section ref={heroRef} className="kf-hero" style={{ height }} aria-label="Introduction">
        <div ref={mediaRef} className="kf-hero-media">
          <img src={pic("hero")} alt="" width={2000} height={1250} decoding="async" />
        </div>
        <div className="kf-hero-copy">
          <div className="kf-wrap">
            <h1 className="kf-h1">
              <Letters text="Think Clearly. Build Fast. Ship with Care." />
            </h1>
            <p className="kf-sub">
              <Words text="The fastest way to give your startup its interface, front-end, and launch site, so you can focus on growth." />
            </p>
            {pill("Book a Free Call")}
          </div>
        </div>
      </section>

      {/* ---- intro + services */}
      <section id="kf-services" className="kf-intro">
        <div className="kf-wrap">
          <h2 className="kf-h2 kf-rv" data-rv="" data-inkblock="" style={rv(30)}>
            <Ink text={INTRO_H2} />
          </h2>
          <div className="kf-rule" />
          <div className="kf-cols">
            <p className="kf-mono kf-rv" data-rv="" data-inkblock="" style={rv(30)}>
              <span className="kf-ink" data-ink="">
                Insights
              </span>
            </p>
            <div className="kf-rv" data-rv="" data-inkblock="" style={rv(30)}>
              {INTRO_P.map((p, i) => (
                <p key={i} className="kf-para">
                  <Ink text={p} />
                </p>
              ))}
            </div>
          </div>
          <div className="kf-grid">
            {SERVICES.map((s, i) => {
              const shot = (
                <div key={"s" + i} className="kf-shot kf-tile" data-rv="" style={{ ["--o" as string]: i * 2 } as CSSProperties}>
                  <img src={pic(s.img)} alt="" width={1200} height={1100} loading="lazy" decoding="async" />
                </div>
              )
              const card = (
                <article key={"c" + i} className="kf-card" style={{ ["--o" as string]: i * 2 + 1 } as CSSProperties}>
                  <div>
                    <h3 className="kf-h3 kf-rv" data-rv="">
                      {s.title}
                    </h3>
                    <ul className="kf-rows">
                      {s.items.map((it, k) =>
                        s.kind === "rows" ? (
                          <li key={k} className="kf-row kf-rv" data-rv="" style={rv(20, (k + 1) * 0.1)}>
                            <span>{it}</span>
                            <span>{"0" + (k + 1)}</span>
                          </li>
                        ) : (
                          <li key={k} className="kf-check kf-rv" data-rv="" style={rv(20, (k + 1) * 0.1)}>
                            <Check />
                            <span>{it}</span>
                          </li>
                        ),
                      )}
                    </ul>
                  </div>
                  <p className="kf-cardfoot kf-rv" data-rv="">
                    {s.foot}
                  </p>
                </article>
              )
              return i % 2 === 0 ? [shot, card] : [card, shot]
            })}
          </div>
        </div>
      </section>

      {/* ---- testimonials */}
      <section
        className="kf-quotes"
        style={{ height, minHeight: 600 }}
        data-quotes=""
        aria-roledescription="carousel"
        aria-label="What clients say"
        onMouseEnter={() => (st.current.paused = true)}
        onMouseLeave={() => (st.current.paused = false)}
        onFocus={() => (st.current.paused = true)}
        onBlur={() => (st.current.paused = false)}
      >
        <div
          className="kf-track"
          style={{ transform: "translateX(" + -slide * 100 + "%)", transition: snap ? "none" : "transform " + SLIDE_DUR + "s " + SLIDE_EASE }}
          onTransitionEnd={onTrackEnd}
        >
          {[...QUOTES, QUOTES[0]].map((q, i) => (
            <figure key={i} className={"kf-slide" + (i === slide ? " kf-on" : "")} aria-hidden={i !== slide} role="group" aria-roledescription="slide" aria-label={(i % QUOTES.length) + 1 + " of " + QUOTES.length}>
              <img src={pic(q.img)} alt="" width={2000} height={1250} loading="lazy" decoding="async" />
              <div className="kf-slide-in">
                <div className="kf-wrap">
                  <div className="kf-qpad">
                    <p className="kf-qlabel kf-q">
                      <i />
                      Testimonials
                    </p>
                    <blockquote className="kf-quote kf-q">{q.text}</blockquote>
                    <figcaption className="kf-who">
                      <span className="kf-q kf-name" style={rv(undefined, 0.1)}>
                        {q.who}
                      </span>
                      <span className="kf-q" style={rv(undefined, 0.2)}>
                        {q.role}
                      </span>
                    </figcaption>
                  </div>
                </div>
              </div>
            </figure>
          ))}
        </div>
        <div className="kf-arrows">
          <button type="button" className="kf-arrow" aria-label="Previous testimonial" onClick={() => go(-1)}>
            <Chevron left />
          </button>
          <button type="button" className="kf-arrow" aria-label="Next testimonial" onClick={() => go(1)}>
            <Chevron />
          </button>
        </div>
      </section>

      {/* ---- process */}
      <section id="kf-process" className="kf-process">
        <div className="kf-wrap">
          <h2 className="kf-h2 kf-rv" data-rv="" data-inkblock="">
            <Ink text={PROCESS_H2} />
          </h2>
          <div className="kf-prow">
            <p className="kf-para kf-rv" data-rv="" data-inkblock="">
              <Ink text="My process is built to give founders clarity and confidence. From the first call to the final release, every step is clear and guided. I focus on understanding your goals, designing the right solution, and refining it together. You stay informed, involved, and supported throughout the entire journey we build together." />
            </p>
            <button type="button" className="kf-btn kf-rv" data-rv="" onClick={() => jump("pricing")}>
              See How It Works
            </button>
          </div>
          <div className="kf-steps">
            {STEPS.map((s, i) => (
              <a key={i} className="kf-step" href={mail} aria-label={s.title + ": " + s.text}>
                <div className="kf-stepcard" data-rv="">
                  <img src={pic(s.img)} alt="" width={760} height={840} loading="lazy" decoding="async" />
                  <div className="kf-steptext">
                    <div className="kf-rv" data-rv="" style={rv(30 + i * 10)}>
                      <h3>{s.title}</h3>
                      <p>{s.text}</p>
                    </div>
                  </div>
                  <div className="kf-stepfoot" aria-hidden="true">
                    <span className="kf-stepgo">
                      <Arrow />
                    </span>
                  </div>
                </div>
              </a>
            ))}
          </div>
        </div>
      </section>

      {/* ---- pricing */}
      <section id="kf-pricing" className="kf-price">
        <div className="kf-wrap">
          <p className="kf-kicker kf-rv" data-rv="">
            Two-Week Launch Sprint
          </p>
          <h2 className="kf-big kf-rv" data-rv="">
            <b>$4,900</b>
            <span>Launch Sprint</span>
          </h2>
          <p className="kf-ideal kf-rv" data-rv="">
            Ideal for founders seeking senior design and front-end help without a long-term commitment.
          </p>
          <p className="kf-incl kf-rv" data-rv="">
            One fixed all-in fee that includes:
          </p>
          <ul className="kf-list">
            {INCLUDED.map(([b, t], i) => (
              <li key={i} className="kf-li kf-rv" data-rv="" style={rv(20, i * 0.05)}>
                <Check />
                <span>{b + " – " + t}</span>
              </li>
            ))}
            <li className="kf-li kf-rv" data-rv="" style={rv(20, INCLUDED.length * 0.05)}>
              <Spark />
              <span>Looking for continuous support? Move to a monthly design partnership for ongoing releases and reviews.</span>
            </li>
          </ul>
          <div className="kf-pfoot">
            <p className="kf-rv" data-rv="">
              Ready to assess and sharpen your product? Book a Launch Sprint with Kedhareswer today.
            </p>
            <a className="kf-btn kf-rv" data-rv="" href={mail} style={{ padding: "12px 30px" }}>
              Check Availability
            </a>
          </div>
        </div>
      </section>

      {/* ---- work */}
      <section id="kf-work" className="kf-work">
        <div className="kf-wrap">
          <h2 className="kf-h2 kf-rv" data-rv="" data-inkblock="">
            <Ink text={"Selected Work & Design Notes—"} soft="Simplified." />
          </h2>
          <p className="kf-lede kf-rv" data-rv="">
            Case studies, process notes, and practical lessons from Kedhareswer&rsquo;s recent work with founders and product teams.
          </p>
          <div className="kf-cards">
            {WORK.map((w, i) => (
              <a key={i} className="kf-wcard" href={mail} aria-label={w.title + ", " + w.meta}>
                <div className="kf-wimg kf-rv" data-rv="" style={rv(40)}>
                  <img src={pic(w.img)} alt="" width={1200} height={800} loading="lazy" decoding="async" />
                </div>
                <h3 className="kf-rv" data-rv="" style={rv(20, 0.1)}>
                  {w.title}
                </h3>
                <p className="kf-rv" data-rv="" style={rv(20, 0.2)}>
                  {w.meta}
                </p>
              </a>
            ))}
          </div>
        </div>
      </section>

      {/* ---- cta */}
      <section className="kf-cta" aria-label="Book a call">
        <img src={pic("cta")} alt="" width={2000} height={1250} loading="lazy" decoding="async" />
        <div className="kf-cta-in">
          <h2 className="kf-rv" data-rv="">
            Get Your Startup&rsquo;s Interface Right From Day One.
          </h2>
          <p className="kf-rv" data-rv="" style={rv(20, 0.1)}>
            Kedhareswer handles the craft. You focus on growth.
          </p>
          <div className="kf-rv" data-rv="" style={rv(20, 0.2)}>
            {pill("Book a Free Call")}
          </div>
        </div>
      </section>

      {/* ---- footer */}
      <footer className="kf-foot">
        <div className="kf-wrap">
          <div className="kf-ftop">
            <div>
              <p className="kf-fbrand">
                <Mark />
                Kedhareswer
              </p>
              <p className="kf-ftag">Think Clearly. Build Fast. Ship with Care.</p>
            </div>
            <div>
              <p className="kf-fh">Main Pages</p>
              <div className="kf-fcols">
                <button type="button" className="kf-flink" onClick={toTop}>
                  Home
                </button>
                {NAV.map((n) => (
                  <button key={n.id} type="button" className="kf-flink" onClick={() => jump(n.id)}>
                    {n.label}
                  </button>
                ))}
                <a className="kf-flink" href={mail}>
                  Contact
                </a>
              </div>
            </div>
            <div>
              <p className="kf-fh">Get in Touch</p>
              <div className="kf-fcol">
                <a className="kf-flink" href={mail}>
                  Email
                </a>
                <a className="kf-flink" href={mail + "?subject=Project%20enquiry"}>
                  Start a project
                </a>
                <a className="kf-flink" href={mail + "?subject=Launch%20Sprint"}>
                  Book a sprint
                </a>
                <button type="button" className="kf-flink" onClick={() => jump("news")}>
                  Newsletter
                </button>
              </div>
            </div>
          </div>
          <div className="kf-fbot" id="kf-news">
            <div>
              <h4>Join the newsletter</h4>
              <p>Keep up to date with everything Kedhareswer.</p>
            </div>
            <form
              className="kf-form"
              onSubmit={(e) => {
                e.preventDefault()
                setSent(true)
              }}
            >
              <label htmlFor="kf-email">Email</label>
              <input id="kf-email" type="email" required placeholder={email} autoComplete="email" onChange={(e) => setReady(e.currentTarget.validity.valid && e.currentTarget.value !== "")} />
              <button type="submit" className={ready ? "kf-ready" : undefined}>
                {sent ? "You’re on the list" : "Get Started"}
              </button>
            </form>
          </div>
        </div>
      </footer>
    </div>
  )
}
